package com.hibernate.ecommerce.model;import jakarta.persistence.Entity;import jakarta.persistence.GeneratedValue;import jakarta.persistence.GenerationType;import jakarta.persistence.Id;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.NotNull;import jakarta.validation.constraints.Positive;import lombok.*;@Entity@Getter@Setter@AllArgsConstructor@NoArgsConstructor@Builderpublic class Product {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @NotNull    @NotBlank    private String name;    @NotNull    @NotBlank    private String description;    @Positive    @NotNull    private Double price;    @Positive    @NotNull    private int stock;}